/**
 * The Second Banquet
 * ------------------
 * Esther names her people and her enemy; Haman pleads on the couch and is hanged on the gallows he built for Mordecai. Stage: the banquet hall again, the queen risen, the king's face in shadow, Haman dragged from the couch; a garden visible through the columns, a gallows in the dark beyond.
 *
 * Palette 0x241810 → 0x060402 · light: dusk · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./esther-kit.js.
 */

import { THREE, createScene, column, throne, oak, tree, well, pillar, person, crowd, birds } from './esther-kit.js';

const BG = 0x241810;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3684729325, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x060402, { band: 0x1b120c });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x17100a });

    /* trees: broadleaf shade */
    oak(W, group, -5.7, 0, -6.6, 1.40, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 74.7, 0, 1.6, 0.99, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 55.4, 0, -54.5, 1.33, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 6.4, 0, -22.7, 0.94, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 25.2, 0, -54.8, 1.07, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    tree(W, group, 5.8, 0, 4.2, 1.1);

    /* garden: shade trees around a well */
    well(W, group, 0.0, 0, 4.9, 1.1);

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x2f1f15, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.39, s: 1.11 });
    person(W, group, [4.5, 0, 6], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.64, s: 1.09 });
    /* crowd: the people of the story */
    crowd(W, group, 0, 16, 23, 70, 44, [0x241810, 0x060402, 0x8a6a44, 0x6a4a30, 0xc8b088, 0x5a4a6a]);

    /* birds: slow circles high above */
    birds(W, group, 8, 55, { y: 26 });

    return W.finish();
}

export default { build };
